<script setup>
import { onMounted, ref } from 'vue'
import ListView from '../shared/components/ListView.vue'

const props = defineProps({ token: { type: String, required: true }, locale: { type: String, default: 'es' } })
const copy = {
  es: { access:'Control de acceso', title:'Usuarios y roles', subtitle:'Administra quién puede entrar y qué módulos puede consultar.', refresh:'Actualizar', users:'Usuarios', roles:'Roles', loading:'Cargando seguridad…', usersTitle:'Usuarios registrados', usersDesc:'Accesos vigentes en la plataforma.', noUsers:'No hay usuarios registrados.', createUser:'Crear usuario', editUser:'Editar usuario', fullName:'Nombre completo', email:'Correo', tempPassword:'Contraseña temporal', role:'Rol', update:'Actualizar', save:'Guardar', cancelUser:'Cancelar usuario', user:'Usuario', rolesCol:'Roles', status:'Estado', actions:'Acciones', active:'Activo', inactive:'Inactivo', noRole:'Sin rol', edit:'Editar', deactivate:'Desactivar', rolesTitle:'Roles disponibles', rolesDesc:'Perfiles que pueden asignarse a los usuarios.', noRoles:'No hay roles registrados.', createRole:'Crear rol', identifier:'Identificador', visibleName:'Nombre visible', permissions:'Permisos', created:'Creado', delete:'Eliminar', cancelRole:'Cancelar rol', pageDate:'es-CO', userUpdated:'Usuario actualizado correctamente.', userCreated:'Usuario creado correctamente.', roleUpdated:'Rol actualizado correctamente.', roleCreated:'Rol creado correctamente.', userDisabled:'Usuario desactivado.', roleDeleted:'Rol eliminado.', confirmUser:'¿Desactivar al usuario {name}?', confirmRole:'¿Eliminar el rol {name}? Esta acción no se puede deshacer.', generic:'No se pudo completar la operación.', permissionLabels:{'Solicitudes':'Solicitudes','Clientes':'Clientes','Pagos':'Pagos','Documentos':'Documentos','Reportes':'Reportes','Usuarios':'Usuarios','Configuración':'Configuración','Servicios y consultas':'Servicios y consultas','Enlaces de agentes':'Enlaces de agentes','Solicitudes asignadas':'Solicitudes asignadas'} },
  en: { access:'Access control', title:'Users and roles', subtitle:'Manage who can sign in and which modules they can access.', refresh:'Refresh', users:'Users', roles:'Roles', loading:'Loading security settings…', usersTitle:'Registered users', usersDesc:'Accounts with access to the platform.', noUsers:'No users found.', createUser:'Create user', editUser:'Edit user', fullName:'Full name', email:'Email', tempPassword:'Temporary password', role:'Role', update:'Update', save:'Save', cancelUser:'Cancel user', user:'User', rolesCol:'Roles', status:'Status', active:'Active', inactive:'Inactive', noRole:'No role', edit:'Edit', deactivate:'Deactivate', rolesTitle:'Available roles', rolesDesc:'Profiles that can be assigned to users.', noRoles:'No roles found.', createRole:'Create role', identifier:'Identifier', visibleName:'Display name', permissions:'Permissions', created:'Created', delete:'Delete', cancelRole:'Cancel role', pageDate:'en-US', userUpdated:'User updated successfully.', userCreated:'User created successfully.', roleUpdated:'Role updated successfully.', roleCreated:'Role created successfully.', userDisabled:'User deactivated.', roleDeleted:'Role deleted.', confirmUser:'Deactivate user {name}?', confirmRole:'Delete role {name}? This action cannot be undone.', generic:'Could not complete the operation.', permissionLabels:{'Solicitudes':'Requests','Clientes':'Clients','Pagos':'Payments','Documentos':'Documents','Reportes':'Reports','Usuarios':'Users','Configuración':'Settings','Servicios y consultas':'Services and consultations','Enlaces de agentes':'Agent links','Solicitudes asignadas':'Assigned requests'} }
}
function t(key, values = {}) { return (copy[props.locale === 'en' ? 'en' : 'es'][key] || key).replace(/\{(\w+)\}/g, (_, name) => values[name] ?? '') }
const tab = ref('users'); const loading = ref(true); const saving = ref(false); const error = ref(''); const notice = ref('')
const users = ref([]); const roles = ref([]); const permissions = ref([])
const userPage = ref({ page: 1, pageSize: 10, totalItems: 0, totalPages: 1 }); const rolePage = ref({ page: 1, pageSize: 10, totalItems: 0, totalPages: 1 })
const userFormOpen = ref(false); const roleFormOpen = ref(false)
const editingUserId = ref(''); const editingRoleId = ref('')
const userForm = ref({ fullName: '', email: '', password: '', roleName: '' }); const roleForm = ref({ name: '', label: '', permissions: [] })

async function request(url, options = {}) { const response = await fetch(url, { ...options, headers: { Authorization: `Bearer ${props.token}`, ...(options.headers || {}) } }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(localizeError(data.error)); return data }
function localizeError(message) { if (props.locale !== 'en') return message || t('generic'); const errors = { 'No se pudo completar la operación.':t('generic'),'Sesión requerida.':'Your session is required.','No tienes permisos para administrar seguridad.':'You do not have permission to manage security.','La base de datos operativa no está configurada.':'The operations database is not configured.','No puedes desactivar tu propia cuenta.':'You cannot deactivate your own account.','Usuario no encontrado.':'User not found.','No puedes eliminar un rol asignado a usuarios. Retíralo primero.':'This role is assigned to users. Remove it from them first.','Rol no encontrado o protegido.':'Role not found or protected.','Nombre, correo y rol son obligatorios.':'Name, email, and role are required.','Ingresa un correo válido.':'Enter a valid email address.','El rol seleccionado no existe.':'The selected role does not exist.','Ya existe un usuario con ese correo.':'A user with that email already exists.','Nombre, correo, contraseña y rol son obligatorios.':'Name, email, password, and role are required.','La contraseña debe tener al menos 10 caracteres.':'Password must be at least 10 characters.','El identificador debe usar letras minúsculas, números, guion o guion bajo.':'Use lowercase letters, numbers, hyphens, or underscores for the identifier.','El nombre visible del rol es obligatorio.':'A display name is required for the role.','Ya existe un rol con ese identificador.':'A role with that identifier already exists.' }; return errors[message] || t('generic') }
function permissionLabel(label) { return copy[props.locale === 'en' ? 'en' : 'es'].permissionLabels[label] || label }
async function loadUsers() { const params = new URLSearchParams({ page: String(userPage.value.page), pageSize: String(userPage.value.pageSize) }); const data = await request(`/api/app/security/users?${params}`); users.value = data.items || []; userPage.value = data.pagination || userPage.value }
async function loadRoles() { const params = new URLSearchParams({ page: String(rolePage.value.page), pageSize: String(rolePage.value.pageSize) }); const data = await request(`/api/app/security/roles?${params}`); roles.value = data.items || []; rolePage.value = data.pagination || rolePage.value; permissions.value = data.permissions || permissions.value }
async function load() { loading.value = true; error.value = ''; try { await Promise.all([loadUsers(), loadRoles()]) } catch (loadError) { error.value = loadError.message } finally { loading.value = false } }
async function saveUser() { saving.value = true; error.value = ''; try { const id = editingUserId.value; await request(id ? `/api/app/security/users/${id}` : '/api/app/security/users', { method: id ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(userForm.value) }); notice.value = t(id ? 'userUpdated' : 'userCreated'); userForm.value = { fullName: '', email: '', password: '', roleName: '' }; editingUserId.value = ''; userFormOpen.value = false; await loadUsers() } catch (saveError) { error.value = saveError.message } finally { saving.value = false } }
async function saveRole() { saving.value = true; error.value = ''; try { const id = editingRoleId.value; await request(id ? `/api/app/security/roles/${id}` : '/api/app/security/roles', { method: id ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(roleForm.value) }); notice.value = t(id ? 'roleUpdated' : 'roleCreated'); roleForm.value = { name: '', label: '', permissions: [] }; editingRoleId.value = ''; roleFormOpen.value = false; await loadRoles() } catch (saveError) { error.value = saveError.message } finally { saving.value = false } }
function editUser(item) { editingUserId.value = item.id; userFormOpen.value = true; userForm.value = { fullName: item.fullName, email: item.email, password: '', roleName: item.roles[0] || '' } }
function editRole(item) { editingRoleId.value = item.id; roleFormOpen.value = true; roleForm.value = { name: item.name, label: item.label, permissions: [...item.permissions] } }
function cancelUserForm() { userFormOpen.value = false; editingUserId.value = ''; userForm.value = { fullName: '', email: '', password: '', roleName: '' } }
function cancelRoleForm() { roleFormOpen.value = false; editingRoleId.value = ''; roleForm.value = { name: '', label: '', permissions: [] } }
async function removeUser(item) { if (!window.confirm(t('confirmUser', { name: item.fullName }))) return; try { await request(`/api/app/security/users/${item.id}`, { method: 'DELETE' }); notice.value = t('userDisabled'); await loadUsers() } catch (removeError) { error.value = removeError.message } }
async function removeRole(item) { if (!window.confirm(t('confirmRole', { name: item.label }))) return; try { await request(`/api/app/security/roles/${item.id}`, { method: 'DELETE' }); notice.value = t('roleDeleted'); await loadRoles() } catch (removeError) { error.value = removeError.message } }
function page(kind, value) { const target = kind === 'users' ? userPage : rolePage; if (value < 1 || value > target.value.totalPages) return; target.value.page = value; kind === 'users' ? loadUsers() : loadRoles() }
onMounted(load)
</script>

<template>
  <section class="module-view security-view"><div class="module-heading"><div><p class="eyebrow">{{ t('access') }}</p><h1>{{ t('title') }}</h1><p>{{ t('subtitle') }}</p></div><button type="button" class="secondary-button compact" @click="load">↻ {{ t('refresh') }}</button></div><div class="security-tabs"><button type="button" :class="{ active: tab === 'users' }" @click="tab = 'users'">{{ t('users') }} <span>{{ userPage.totalItems }}</span></button><button type="button" :class="{ active: tab === 'roles' }" @click="tab = 'roles'">{{ t('roles') }} <span>{{ rolePage.totalItems }}</span></button></div><p v-if="notice" class="security-notice">{{ notice }}</p><p v-if="error" class="request-error">{{ error }}</p><div v-if="loading" class="module-state panel">{{ t('loading') }}</div>
    <ListView v-else-if="tab === 'users'" :locale="locale" :title="t('usersTitle')" :description="t('usersDesc')" :count="userPage.totalItems" :page="userPage.page" :total-pages="userPage.totalPages" :empty="!users.length" :empty-text="t('noUsers')" @previous="page('users', userPage.page - 1)" @next="page('users', userPage.page + 1)"><template #actions><button type="button" class="primary-button compact" @click="userFormOpen = !userFormOpen; editingUserId = ''">+ {{ t(editingUserId ? 'editUser' : 'createUser') }}</button></template><template #toolbar><form v-if="userFormOpen" class="security-inline-form" @submit.prevent="saveUser"><input v-model="userForm.fullName" :placeholder="t('fullName')" required /><input v-model="userForm.email" type="email" :placeholder="t('email')" required /><input v-if="!editingUserId" v-model="userForm.password" type="password" minlength="10" :placeholder="t('tempPassword')" required /><select v-model="userForm.roleName" required><option value="" disabled>{{ t('role') }}</option><option v-for="role in roles" :key="role.name" :value="role.name">{{ role.label }}</option></select><button type="submit" class="primary-button compact" :disabled="saving">{{ t(editingUserId ? 'update' : 'save') }}</button></form></template><template #columns><th>{{ t('user') }}</th><th>{{ t('email') }}</th><th>{{ t('rolesCol') }}</th><th>{{ t('status') }}</th><th>{{ t('actions') }}</th></template><template #rows><tr v-for="item in users" :key="item.id"><td><div class="table-person"><span class="avatar avatar-table">{{ item.fullName.slice(0, 2).toUpperCase() }}</span><strong>{{ item.fullName }}</strong></div></td><td>{{ item.email }}</td><td>{{ item.roles.join(' · ') || t('noRole') }}</td><td><span :class="['security-status', { inactive: !item.active }]">{{ item.active ? t('active') : t('inactive') }}</span></td><td><button type="button" class="secondary-button compact" @click="editUser(item)">{{ t('edit') }}</button> <button v-if="item.active" type="button" class="danger-link" @click="removeUser(item)">{{ t('deactivate') }}</button></td></tr></template></ListView>
    <ListView v-else :locale="locale" :title="t('rolesTitle')" :description="t('rolesDesc')" :count="rolePage.totalItems" :page="rolePage.page" :total-pages="rolePage.totalPages" :empty="!roles.length" :empty-text="t('noRoles')" @previous="page('roles', rolePage.page - 1)" @next="page('roles', rolePage.page + 1)"><template #actions><button type="button" class="primary-button compact" @click="roleFormOpen = !roleFormOpen; editingRoleId = ''">+ {{ t('createRole') }}</button></template><template #toolbar><form v-if="roleFormOpen" class="security-inline-form role-inline-form" @submit.prevent="saveRole"><input v-model="roleForm.name" :placeholder="t('identifier')" pattern="[a-z][a-z0-9_-]{2,40}" :disabled="Boolean(editingRoleId)" required /><input v-model="roleForm.label" :placeholder="t('visibleName')" required /><div class="inline-permissions"><label v-for="permission in permissions" :key="permission.code"><input v-model="roleForm.permissions" type="checkbox" :value="permission.code" />{{ permissionLabel(permission.label) }}</label></div><button type="submit" class="primary-button compact" :disabled="saving">{{ t(editingRoleId ? 'update' : 'save') }}</button></form></template><template #columns><th>{{ t('role') }}</th><th>{{ t('identifier') }}</th><th>{{ t('permissions') }}</th><th>{{ t('created') }}</th><th>{{ t('actions') }}</th></template><template #rows><tr v-for="item in roles" :key="item.id"><td><strong>{{ item.label }}</strong></td><td>{{ item.name }}</td><td><span class="count-badge">{{ item.permissions.length }}</span></td><td>{{ new Date(item.createdAt).toLocaleDateString(t('pageDate')) }}</td><td><button type="button" class="secondary-button compact" @click="editRole(item)">{{ t('edit') }}</button> <button type="button" class="danger-link" @click="removeRole(item)">{{ t('delete') }}</button></td></tr></template></ListView>
    <div v-if="userFormOpen || roleFormOpen" class="security-cancel-bar"><button v-if="userFormOpen" type="button" class="secondary-button compact" @click="cancelUserForm">{{ t('cancelUser') }}</button><button v-if="roleFormOpen" type="button" class="secondary-button compact" @click="cancelRoleForm">{{ t('cancelRole') }}</button></div>
  </section>
</template>

<style scoped>
.security-inline-form{display:grid;grid-template-columns:1fr 1fr 1fr 180px auto;gap:8px;padding:12px;border:1px solid #e5eaf0;border-radius:8px;background:#f8fafc}.security-inline-form input,.security-inline-form select{min-height:35px;padding:0 9px;border:1px solid #d8e0ea;border-radius:6px;color:#344b60;background:#fff;font-size:10px}.role-inline-form{grid-template-columns:1fr 1fr auto}.inline-permissions{display:flex;align-items:center;flex-wrap:wrap;gap:8px;grid-column:1/-1;padding-top:4px;color:#526174;font-size:9px}.inline-permissions label{display:flex;gap:4px;align-items:center}.danger-link{padding:0;border:0;color:#b54747;background:transparent;font-size:10px;font-weight:800;cursor:pointer}.danger-link:hover{text-decoration:underline}@media(max-width:800px){.security-inline-form,.role-inline-form{grid-template-columns:1fr}.inline-permissions{grid-column:auto}}
.security-cancel-bar{display:flex;justify-content:flex-end;gap:8px;margin-top:10px}
</style>
